const item = $input.first();
const j = item.json;

const prompt = String(j.prompt ?? '').trim();
if (!prompt) {
  throw new Error('Missing prompt. Send POST JSON with a non-empty "prompt" field.');
}

const rawBase = String(j.baseUrl ?? '').trim().replace(/\\/+$/, '');
let parsed;
try {
  parsed = new URL(rawBase);
} catch {
  throw new Error('AI Provider Configuration: baseUrl must be a valid absolute URL.');
}
if (!['https:', 'http:'].includes(parsed.protocol)) {
  throw new Error('AI Provider Configuration: baseUrl must use HTTP or HTTPS.');
}
if (parsed.username || parsed.password) {
  throw new Error('Do not place credentials in baseUrl. Configure authentication using n8n credentials.');
}

const model = String(j.model ?? '').trim();
if (!model || model === 'YOUR_MODEL_ID') {
  throw new Error('Configure a valid model ID in the AI Provider Configuration node.');
}

return [{
  json: {
    baseUrl: rawBase,
    model,
    systemPrompt: String(j.systemPrompt ?? ''),
    prompt,
    temperature: Number(j.temperature ?? 0.2),
    maxTokens: Math.max(1, Math.min(32000, Number(j.maxTokens ?? 2000))),
    requestId: j.body?.requestId ?? j.requestId ?? null
  }
}];

const response = $input.first().json;
const choices = response?.choices;
if (!Array.isArray(choices) || !choices[0]?.message) {
  const status = response?.statusCode ?? response?.status ?? null;
  const detail = response?.error?.message ?? response?.message ?? 'Provider response did not contain choices[0].message.';
  return [{ json: { ok: false, error: String(detail), statusCode: status, providerResponse: response } }];
}

return [{
  json: {
    ok: true,
    model: response.model ?? null,
    content: choices[0].message.content ?? '',
    finishReason: choices[0].finish_reason ?? null,
    usage: response.usage ?? null,
    providerResponseId: response.id ?? null
  }
}];
